        return 0
    m = len(bin(a))-3
    if m + 1 < k:
        return 0
    if k == 1:
        return m+1
    if m + 1 == k:
        return Numb(a & ((1<<m)-1), k-1)
    return C[m][k]+Numb(a & ((1<<m)-1), k-1)

